__NUXT_JSONP__("/posts/ui-prototypes-with-protopie", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C){return {data:[{post:{slug:u,description:"Quick review of Protopie, a quite new exciting prototyping tool!",title:"UI Prototypes with Protopie",type:d,imgCover:u,tags:[g,"After Effects","Sketch",j,d],createdAt:"2021-05-18T00:00:00.000Z",toc:[{id:v,depth:h,text:w},{id:x,depth:h,text:g},{id:y,depth:h,text:z}],body:{type:"root",children:[{type:b,tag:k,props:{id:v},children:[{type:b,tag:f,props:{href:"#context--web-animations",ariaHidden:l,tabIndex:m},children:[{type:b,tag:n,props:{className:[o,p]},children:[]}]},{type:a,value:w}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I'm still on the design side these days, even if I keep up developing using React at the same time, but not that easy. Though, the good part of this, is that UI design is very complementary with web development, and mastering a wider part of the production chain is very interesting."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"As a front-end developer, I have to deal with web animations & interactions on a regular basis. Most of the time, I get by ok just using css rules or @keyframes."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Recently, I discovered "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.framer.com\u002Fmotion\u002F",rel:[q,r,s],target:t},children:[{type:a,value:"Framer motion"}]},{type:a,value:" that suddenly opened new doors. For complex animations, such as illustration popovers, After Effect + Lottie integrations have become my go-to solution. But until now, I never jumped into the prototyping tools wagon."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Having used Framer motion, the most obvious one was "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.framer.com\u002F",rel:[q,r,s],target:t},children:[{type:a,value:"Framer"}]},{type:a,value:", but one of my fellow already used "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.protopie.io\u002F",rel:[q,r,s],target:t},children:[{type:a,value:g}]},{type:a,value:" which I previously never heard of."}]},{type:a,value:c},{type:b,tag:k,props:{id:x},children:[{type:b,tag:f,props:{href:"#protopie",ariaHidden:l,tabIndex:m},children:[{type:b,tag:n,props:{className:[o,p]},children:[]}]},{type:a,value:g}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"To quickly summarize, it's a prototyping software that can be connected with Sketch (but also Figma and Adobe XD) through the provided plugin, and allow us to bring any kind of advanced interactions\u002Fanimations from our Sketch artboards for demo purpose."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"So it encompasses a dedicated desktop application to build prototype, but also a Cloud to host and share our prototype to others. The app has a built-in previewer to run our Prototype, and the overall interface is very neat."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Protopie is built with simplicity in mind, around logical concepts that make sense (trigger type binded to object in the layer panel, with responses nested as actions). It's mostly a no-code tool, but we might use a formula system for advanced use-case that take advantage of variables."}]},{type:a,value:c},{type:b,tag:k,props:{id:y},children:[{type:b,tag:f,props:{href:"#my-feeling",ariaHidden:l,tabIndex:m},children:[{type:b,tag:n,props:{className:[o,p]},children:[]}]},{type:a,value:z}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Protopie has a bunch of features that make it really appealing and enjoyable to use:"}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:i,props:{},children:[{type:a,value:"a neat desktop app interface"}]},{type:a,value:c},{type:b,tag:i,props:{},children:[{type:a,value:"a very handy Sketch plugin"}]},{type:a,value:c},{type:b,tag:i,props:{},children:[{type:a,value:"a synchronised Cloud to share our ideas"}]},{type:a,value:c},{type:b,tag:i,props:{},children:[{type:a,value:"a very user-friendly platform and community"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"The only concern is about the price (11$\u002Fmonth as I'm writing this) with a 30 days trial, the time needed to be hooked 😍."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I wish I can keep playing more with it as possibilities seems endless!"}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Fui-prototypes-with-protopie",extension:".md",updatedAt:"2025-10-10T15:29:17.529Z"},relatedPosts:[{title:"Building a 2D runner game with Next.js",type:d,imgCover:"building-a-2d-runner-game-with-nextjs",tags:["games","next","framer-motion","Tailwind","Figma","devs",A,d],createdAt:"2024-08-17T00:00:00.000Z",path:"\u002Fposts\u002Fbuilding-a-2D-runner-game-with-nextjs"},{title:"Animated movie WIP#2",type:d,imgCover:"animated-movie-wip2",tags:[A,d],createdAt:"2018-04-06T00:00:00.000Z",path:"\u002Fposts\u002Fanimated-movie-wip2"},{title:"Nuxt + Firebase with @nuxt\u002Ffirebase",type:d,imgCover:"nuxt-firebase-part-0-serie-introduction",tags:[B,"vue","firebase",j,d],createdAt:"2021-01-07T00:00:00.000Z",path:"\u002Fposts\u002Fnuxt-firebase-with-@nuxt-firebase"},{title:"How video games inspire front-end",type:d,imgCover:"how-video-games-inspire-front-end.png",tags:["game",B,"cordova",j,d],createdAt:"2021-12-11T00:00:00.000Z",path:"\u002Fposts\u002Fhow-video-games-inspire-front-end"}]}],fetch:[{counter:C},{counter:C},{counter:h},{counter:24},{counter:72}],mutations:[]}}("text","element","\n","article","p","a","Protopie",2,"li","miscs","h2","true",-1,"span","icon","icon-link","nofollow","noopener","noreferrer","_blank","ui-prototypes-with-protopie","context--web-animations","Context & web animations","protopie","my-feeling","My feeling","cinema 4D","nuxt",1)));